# =============================================================================
# Shen et al. (Nature Aging, 2024) pathway similarity network for transcriptomics
#
# Input: all_pathway_enrichment_results.csv (all tested GO BP, KEGG and
#        Reactome terms) generated by
#        02-transcriptomics_pathway_molecular_expression_heatmap.R.
# Filter the saved BH-adjusted P values at PATHWAY_NETWORK_FDR; do not rerun
# enrichment or adjust P values again. Every significant term enters stage 1.
# Output: two-stage pathway similarity networks, functional modules, GraphML
#         files and one publication-quality final network figure per crest.
#
# Similarity methods follow Shen et al.; network cutoffs use the requested
# Jia 2026 settings:
#   1. GO BP: Wang semantic similarity, retain similarities >= 0.5.
#   2. KEGG: gene-set Jaccard similarity, retain values >= 0.3.
#   3. Reactome: gene-set Jaccard similarity, retain values >= 0.5.
#   4. Detect communities with edge-betweenness clustering and retain the term
#      with the smallest BH-adjusted P value as each module representative.
#   5. Merge representatives from all databases and repeat the module analysis
#      Jaccard similarity >= 0.3 to obtain final functional modules.
#   6. Display the top 15 final modules using Jaccard similarity >= 0.1.
#      Show one final representative per module and detect display communities
#      at this cutoff for the coloured envelopes (Jia-style visualization).
#      This limit applies only to the figure, after all modules are saved.
#      It is independent of the heatmap's top-15 pathways per crest.
#
# All pathway memberships and ontology information are read locally. No network
# access is used. Similarities are calculated independently for each DE-SWAN
# crest so annotations from different biological events cannot be merged.
# =============================================================================

get_script_dir <- function() {
  args <- commandArgs(trailingOnly = FALSE)
  file_arg <- grep("^--file=", args, value = TRUE)
  if (length(file_arg) > 0) {
    return(dirname(normalizePath(sub("^--file=", "", file_arg[1]), winslash = "/")))
  }
  source_file <- tryCatch(sys.frame(1)$ofile, error = function(e) NULL)
  if (!is.null(source_file)) {
    return(dirname(normalizePath(source_file, winslash = "/")))
  }
  normalizePath(getwd(), winslash = "/")
}

setwd(get_script_dir())

