assert_file <- function(path) {
  if (!file.exists(path)) stop("Required input does not exist: ", path)
  normalizePath(path, winslash = "/")
}

assert_columns <- function(df, required, object_name) {
  missing <- setdiff(required, names(df))
  if (length(missing) > 0) {
    stop(object_name, " is missing columns: ", paste(missing, collapse = ", "))
  }
}

safe_token <- function(x) {
  x <- gsub("[^A-Za-z0-9]+", "_", as.character(x))
  gsub("(^_+|_+$)", "", x)
}

format_age <- function(x) {
  ifelse(abs(x - round(x)) < 1e-8, as.character(round(x)), format(x, digits = 3))
}

sentence_case <- function(x) {
  x <- trimws(as.character(x))
  has_text <- !is.na(x) & nzchar(x)
  first_word <- sub("[^[:alpha:]].*$", "", x)
  preserve_case <- first_word %in% c("mRNA", "tRNA", "rRNA", "ncRNA", "miRNA",
                                    "lncRNA", "cAMP", "cGMP")
  change_case <- has_text & !preserve_case
  x[change_case] <- paste0(toupper(substr(x[change_case], 1, 1)), substring(x[change_case], 2))
  x
}

wrap_label <- function(x, width = 38L) {
  vapply(
    as.character(x),
    function(value) paste(strwrap(value, width = width), collapse = "\n"),
    character(1)
  )
}

assert_positive_scalar <- function(value, name) {
  if (length(value) != 1L || !is.finite(value) || value <= 0) {
    stop(name, " must be one positive finite value")
  }
  invisible(value)
}

