# Reference-style layout: black labels close to nodes, with measured clearance.
# Geometry is in millimetres of the final panel, not biological coordinates.
measure_network_labels <- function(nodes) {
  grDevices::pdf(file = NULL, family = "Helvetica")
  on.exit(grDevices::dev.off(), add = TRUE)
  label_gp <- grid::gpar(fontfamily = "Helvetica", fontsize = NETWORK_LABEL_SIZE_PT,
                          lineheight = 1.05)
  nodes$network_label <- sentence_case(nodes$description)
  nodes$label_width_mm <- nodes$label_height_mm <- NA_real_
  for (i in seq_len(nrow(nodes))) {
    width <- 32L
    repeat {
      label <- wrap_label(sentence_case(nodes$description[i]), width = width)
      grob <- grid::textGrob(label, gp = label_gp)
      label_width <- grid::convertWidth(grid::grobWidth(grob), "mm", valueOnly = TRUE)
      if (label_width <= 0.30 * FIGURE_WIDTH_MM || width <= 8L) break
      width <- width - 1L
    }
    nodes$network_label[i] <- label
    nodes$label_width_mm[i] <- label_width + 1.0
    nodes$label_height_mm[i] <-
      grid::convertHeight(grid::grobHeight(grob), "mm", valueOnly = TRUE) + 1.0
  }
  nodes
}

edges_cross_box <- function(edges, box) {
  if (!nrow(edges)) return(logical())
  dx <- edges$x_to - edges$x_from
  dy <- edges$y_to - edges$y_from
  tx <- cbind((box[1] - edges$x_from) / dx, (box[2] - edges$x_from) / dx)
  ty <- cbind((box[3] - edges$y_from) / dy, (box[4] - edges$y_from) / dy)
  parallel_x <- abs(dx) < 1e-10
  parallel_y <- abs(dy) < 1e-10
  tx[parallel_x, ] <- rep(c(-Inf, Inf), each = sum(parallel_x))
  ty[parallel_y, ] <- rep(c(-Inf, Inf), each = sum(parallel_y))
  outside <- (parallel_x & (edges$x_from < box[1] | edges$x_from > box[2])) |
    (parallel_y & (edges$y_from < box[3] | edges$y_from > box[4]))
  enter <- pmax(0, pmin(tx[, 1], tx[, 2]), pmin(ty[, 1], ty[, 2]))
  leave <- pmin(1, pmax(tx[, 1], tx[, 2]), pmax(ty[, 1], ty[, 2]))
  !outside & enter <= leave
}

layout_network_labels <- function(nodes, edges, panel_height_mm, seed) {
  labels <- measure_network_labels(nodes)
  node_radius <- max(NETWORK_NODE_SIZE_MM) / 2 + 0.5
  candidates <- lapply(seq_len(nrow(labels)), function(i) {
    w <- labels$label_width_mm[i]
    h <- labels$label_height_mm[i]
    above_below <- expand.grid(shift = c(0, -0.3, 0.3, -0.5, 0.5),
                              side = c(1, -1), gap = c(0.5, 2, 4))
    beside <- expand.grid(shift = c(0, -0.5, 0.5), side = c(1, -1),
                          gap = c(0.5, 2, 4))
    positions <- rbind(
      cbind(labels$x[i] + above_below$shift * w,
            labels$y[i] + above_below$side * (h / 2 + node_radius + above_below$gap)),
      cbind(labels$x[i] + beside$side * (w / 2 + node_radius + beside$gap),
            labels$y[i] + beside$shift * h)
    )
    boxes <- cbind(positions[, 1] - w / 2, positions[, 1] + w / 2,
                   positions[, 2] - h / 2, positions[, 2] + h / 2)
    keep <- boxes[, 1] >= 0.35 & boxes[, 2] <= FIGURE_WIDTH_MM - 0.35 &
      boxes[, 3] >= 0.35 & boxes[, 4] <= panel_height_mm - 0.35
    positions <- positions[keep, , drop = FALSE]
    boxes <- boxes[keep, , drop = FALSE]
    if (!nrow(boxes)) stop("No room for pathway label; increase figure height: ",
                           labels$description[i])
    intrinsic <- vapply(seq_len(nrow(boxes)), function(k) {
      b <- boxes[k, ]
      node_dx <- pmax(b[1] - labels$x, 0, labels$x - b[2])
      node_dy <- pmax(b[3] - labels$y, 0, labels$y - b[4])
      node_distance <- sqrt(node_dx^2 + node_dy^2)
      collisions <- sum(node_distance < node_radius) + sum(edges_cross_box(edges, b))
      ambiguity <- sum(node_distance < node_distance[i] - 0.25)
      1e5 * collisions + 30 * ambiguity + node_distance[i] +
        0.1 * sqrt(sum((positions[k, ] - c(labels$x[i], labels$y[i]))^2))
    }, numeric(1))
    list(positions = positions, boxes = boxes, cost = intrinsic)
  })
  overlap_area <- function(box, others) {
    if (!nrow(others)) return(0)
    sum(pmax(0, pmin(box[2], others[, 2]) - pmax(box[1], others[, 1])) *
          pmax(0, pmin(box[4], others[, 4]) - pmax(box[3], others[, 3])))
  }
  set.seed(seed)
  best <- NULL
  best_cost <- Inf
  for (attempt in seq_len(10L)) {
    visit <- if (attempt == 1L) order(-labels$label_width_mm * labels$label_height_mm)
      else sample(seq_len(nrow(labels)))
    chosen <- rep(NA_integer_, nrow(labels))
    boxes <- matrix(NA_real_, nrow(labels), 4)
    for (sweep in seq_len(3L)) {
      for (i in visit) {
        others <- boxes[setdiff(which(!is.na(chosen)), i), , drop = FALSE]
        candidate <- candidates[[i]]
        cost <- candidate$cost + 1e5 * vapply(seq_len(nrow(candidate$boxes)),
          function(k) overlap_area(candidate$boxes[k, ], others), numeric(1))
        chosen[i] <- which.min(cost)
        boxes[i, ] <- candidate$boxes[chosen[i], ]
      }
    }
    total <- sum(vapply(seq_along(chosen), function(i) {
      candidates[[i]]$cost[chosen[i]] +
        1e5 * overlap_area(boxes[i, ], boxes[-i, , drop = FALSE])
    }, numeric(1)))
    if (total < best_cost) {
      best_cost <- total
      best <- chosen
    }
  }
  xy <- do.call(rbind, lapply(seq_along(best), function(i) candidates[[i]]$positions[best[i], ]))
  labels$label_x <- xy[, 1]
  labels$label_y <- xy[, 2]
  labels$label_hjust <- 0.5
  attr(labels, "layout_cost") <- best_cost
  labels
}

separate_network_nodes <- function(coordinates, xlim, ylim, clearance_mm = 8) {
  if (nrow(coordinates) < 2L) return(coordinates)
  for (iteration in seq_len(300L)) {
    largest_overlap <- 0
    for (i in seq_len(nrow(coordinates) - 1L)) {
      for (j in (i + 1L):nrow(coordinates)) {
        delta <- coordinates[j, ] - coordinates[i, ]
        distance <- sqrt(sum(delta^2))
        overlap <- clearance_mm - distance
        if (overlap <= 0) next
        largest_overlap <- max(largest_overlap, overlap)
        direction <- if (distance > 1e-8) delta / distance else c(1, 0)
        coordinates[i, ] <- coordinates[i, ] - direction * overlap / 2
        coordinates[j, ] <- coordinates[j, ] + direction * overlap / 2
      }
    }
    coordinates[, 1] <- pmax(xlim[1], pmin(xlim[2], coordinates[, 1]))
    coordinates[, 2] <- pmax(ylim[1], pmin(ylim[2], coordinates[, 2]))
    if (largest_overlap < 0.01) break
  }
  coordinates
}

# Independent adaptation of the Jia repository's representative-node display:
# community detection at the display cutoff, circular nodes, pale envelopes,
# black labels, and edge width proportional to Jaccard similarity.
# Analysis memberships and gene-set definitions remain those of this script.
build_reference_network_figure <- function(network_nodes, edges, title, title_colour, seed) {
  # Canonical ordering keeps the same graph layout when edges arrive from a
  # freshly computed matrix or a previously exported, sorted source table.
  network_nodes <- dplyr::arrange(network_nodes, .data$figure_module_rank, .data$term_uid)
  endpoints <- cbind(pmin(edges$from_uid, edges$to_uid), pmax(edges$from_uid, edges$to_uid))
  edges$from_uid <- endpoints[, 1]
  edges$to_uid <- endpoints[, 2]
  edges <- dplyr::arrange(edges, dplyr::desc(.data$similarity), .data$from_uid, .data$to_uid)
  display_modules <- detect_modules(network_nodes$term_uid,
                                    dplyr::select(edges, "from_uid", "to_uid", "similarity"),
                                    paste0("C", network_nodes$crest_id[1], "_DISPLAY"))
  graph <- display_modules$graph
  network_nodes$display_community_id <- unname(display_modules$module_id[network_nodes$term_uid])
  community_key <- network_nodes |>
    dplyr::group_by(.data$display_community_id) |>
    dplyr::summarise(n = dplyr::n(), p = min(.data$p_adjust), .groups = "drop") |>
    dplyr::arrange(dplyr::desc(.data$n), .data$p, .data$display_community_id)
  network_nodes <- network_nodes |>
    dplyr::mutate(
      display_module_rank = .data$figure_module_rank,
      module_tag = paste0("M", .data$figure_module_rank),
      display_community = paste0("C", match(.data$display_community_id, community_key$display_community_id)),
      n_community_pathways = community_key$n[match(.data$display_community_id, community_key$display_community_id)],
      n_pathways = 1L, n_databases = 1L,
      displayed_representative_uid = .data$term_uid,
      is_display_representative = TRUE,
      network_label = sentence_case(.data$description),
      figure_minus_log10_fdr = pmin(.data$minus_log10_fdr, FDR_SIZE_CAP)
    )
  panel_height_mm <- FIGURE_HEIGHT_MM - 9
  set.seed(seed)
  base_layout <- igraph::layout_with_fr(graph, weights = rep(1, igraph::ecount(graph)), niter = 3000)
  best_cost <- Inf
  best <- NULL
  for (angle in c(0, pi / 4, pi / 2, -pi / 4)) {
    rotation <- matrix(c(cos(angle), sin(angle), -sin(angle), cos(angle)), 2, 2)
    xy <- base_layout %*% rotation
    xlim <- FIGURE_WIDTH_MM * c(0.27, 0.73)
    ylim <- c(6, panel_height_mm - 6)
    xy <- igraph::norm_coords(xy, xmin = xlim[1], xmax = xlim[2], ymin = ylim[1], ymax = ylim[2])
    xy <- separate_network_nodes(xy, xlim, ylim)
    coords <- data.frame(term_uid = igraph::V(graph)$name, x = xy[, 1], y = xy[, 2])
    plot_nodes <- dplyr::left_join(network_nodes, coords, by = "term_uid")
    plot_edges <- edges |>
      dplyr::left_join(dplyr::rename(coords, from_uid = "term_uid", x_from = "x", y_from = "y"), by = "from_uid") |>
      dplyr::left_join(dplyr::rename(coords, to_uid = "term_uid", x_to = "x", y_to = "y"), by = "to_uid")
    label_nodes <- layout_network_labels(plot_nodes, plot_edges, panel_height_mm, seed)
    cost <- attr(label_nodes, "layout_cost")
    if (cost < best_cost) {
      best_cost <- cost
      best <- list(nodes = label_nodes, edges = plot_edges)
    }
    # Compare all orientations: zero collisions alone is not sufficient if a
    # distant label would appear closer to a different pathway's node.
  }
  if (best_cost >= 1e4) stop("Unable to place all pathway labels without collisions; increase figure height")
  plot_nodes <- best$nodes
  plot_edges <- best$edges
  # Fill the requested width using the measured text and envelope extents.
  # Text stays at its original point size; only non-quantitative x coordinates
  # expand, which preserves the clearance established by the label solver.
  x_centres <- c(plot_nodes$x, plot_nodes$label_x)
  half_widths <- c(rep(1.8, nrow(plot_nodes)), plot_nodes$label_width_mm / 2)
  span <- function(scale) diff(range(c(scale * x_centres - half_widths,
                                       scale * x_centres + half_widths)))
  x_scale <- if (span(1) < FIGURE_WIDTH_MM - 0.7) {
    stats::uniroot(function(scale) span(scale) - (FIGURE_WIDTH_MM - 0.7),
                    interval = c(1, 100))$root
  } else 1
  x_offset <- 0.35 - min(x_scale * x_centres - half_widths)
  plot_nodes$x <- plot_nodes$x * x_scale + x_offset
  plot_nodes$label_x <- plot_nodes$label_x * x_scale + x_offset
  plot_edges$x_from <- plot_edges$x_from * x_scale + x_offset
  plot_edges$x_to <- plot_edges$x_to * x_scale + x_offset
  plot_nodes$label_guide_x <- pmax(plot_nodes$label_x - plot_nodes$label_width_mm / 2,
                                  pmin(plot_nodes$label_x + plot_nodes$label_width_mm / 2, plot_nodes$x))
  plot_nodes$label_guide_y <- pmax(plot_nodes$label_y - plot_nodes$label_height_mm / 2,
                                  pmin(plot_nodes$label_y + plot_nodes$label_height_mm / 2, plot_nodes$y))
  guide_dx <- plot_nodes$label_guide_x - plot_nodes$x
  guide_dy <- plot_nodes$label_guide_y - plot_nodes$y
  guide_length <- sqrt(guide_dx^2 + guide_dy^2)
  ambiguous <- vapply(seq_len(nrow(plot_nodes)), function(i) {
    dx <- pmax(abs(plot_nodes$x - plot_nodes$label_x[i]) - plot_nodes$label_width_mm[i] / 2, 0)
    dy <- pmax(abs(plot_nodes$y - plot_nodes$label_y[i]) - plot_nodes$label_height_mm[i] / 2, 0)
    any(sqrt(dx^2 + dy^2) < guide_length[i] - 0.25)
  }, logical(1))
  plot_nodes$show_label_guide <- ambiguous | guide_length > 4
  plot_nodes$label_guide_start_x <- plot_nodes$x + 1.7 * guide_dx / pmax(guide_length, 1e-8)
  plot_nodes$label_guide_start_y <- plot_nodes$y + 1.7 * guide_dy / pmax(guide_length, 1e-8)
  community_lookup <- stats::setNames(plot_nodes$display_community_id, plot_nodes$term_uid)
  plot_edges$within_display_community <- unname(community_lookup[plot_edges$from_uid]) ==
    unname(community_lookup[plot_edges$to_uid])
  # A convex envelope around small circles gives rounded ends for two-node or
  # nearly collinear communities without spline overshoot beyond the nodes.
  hull_nodes <- dplyr::bind_rows(lapply(split(plot_nodes, plot_nodes$display_community), function(group) {
    if (nrow(group) < 2L) return(NULL)
    angles <- seq(0, 2 * pi, length.out = 49L)[-49L]
    points <- data.frame(
      x = rep(group$x, each = length(angles)) + 1.8 * rep(cos(angles), nrow(group)),
      y = rep(group$y, each = length(angles)) + 1.8 * rep(sin(angles), nrow(group))
    )
    points <- points[grDevices::chull(points$x, points$y), ]
    points$display_community <- group$display_community[1]
    points$hull_colour <- paste0("Hull_", group$display_community[1])
    points
  }))
  hull_colours <- vapply(DISPLAY_COMMUNITY_COLOURS, function(colour) {
    rgb <- 0.3 * grDevices::col2rgb(colour) + 0.7 * 255
    grDevices::rgb(rgb[1], rgb[2], rgb[3], maxColorValue = 255)
  }, character(1))
  hull_colours[1:3] <- c("#C7DEF8", "#E7BFC0", "#FDF1D1")
  names(hull_colours) <- paste0("Hull_", names(hull_colours))
  module_key <- plot_nodes |>
    dplyr::transmute(
      crest_id, crest_label, peak_age, final_module_id, figure_module_rank,
      displayed_representative_uid, representative_description = sentence_case(.data$description),
      representative_database = .data$database, representative_p_adjust = .data$p_adjust,
      n_pathways, n_databases, databases = .data$database, display_module_rank, module_tag,
      module_detail = "", network_label, display_community_id, display_community,
      n_community_pathways, label_x, label_y, label_width_mm, label_height_mm
    )
  fdr_min <- -log10(FDR_THRESHOLD)
  size_breaks <- c(2, 5, FDR_SIZE_CAP)
  size_breaks <- sort(unique(size_breaks[size_breaks >= fdr_min & size_breaks <= FDR_SIZE_CAP]))
  size_labels <- format(size_breaks, trim = TRUE)
  size_labels[length(size_labels)] <- paste0(">=", tail(size_labels, 1))
  plot <- ggplot2::ggplot() +
    ggplot2::geom_polygon(
      data = hull_nodes,
      ggplot2::aes(x = .data$x, y = .data$y, group = .data$display_community,
                    fill = .data$hull_colour),
      colour = NA, show.legend = FALSE
    ) +
    ggplot2::geom_segment(
      data = plot_edges,
      ggplot2::aes(x = .data$x_from, y = .data$y_from, xend = .data$x_to, yend = .data$y_to,
                    linewidth = .data$similarity),
      colour = "#A0A0A0", lineend = "round", show.legend = FALSE
    ) +
    ggplot2::geom_segment(
      data = plot_nodes |> dplyr::filter(.data$show_label_guide),
      ggplot2::aes(x = .data$label_guide_start_x, y = .data$label_guide_start_y,
                    xend = .data$label_guide_x, yend = .data$label_guide_y),
      colour = "#888888", linewidth = 0.12, linetype = "dotted", show.legend = FALSE
    ) +
    ggplot2::geom_point(
      data = plot_nodes,
      ggplot2::aes(x = .data$x, y = .data$y, fill = .data$display_community,
                    size = .data$figure_minus_log10_fdr),
      shape = 21, colour = "#171717", stroke = 0.2
    ) +
    ggplot2::geom_text(
      data = plot_nodes,
      ggplot2::aes(x = .data$label_x, y = .data$label_y, label = .data$network_label),
      colour = "#171717", family = "Helvetica", size = NETWORK_LABEL_SIZE_PT / PT_PER_MM,
      lineheight = 1.05, hjust = 0.5, vjust = 0.5, show.legend = FALSE
    ) +
    ggplot2::scale_fill_manual(values = c(DISPLAY_COMMUNITY_COLOURS, hull_colours), guide = "none") +
    ggplot2::scale_size_continuous(
      name = "-log10(FDR)", range = NETWORK_NODE_SIZE_MM,
      limits = c(fdr_min, FDR_SIZE_CAP), breaks = size_breaks, labels = size_labels
    ) +
    ggplot2::scale_linewidth_continuous(range = c(0.12, 0.45),
                                        limits = c(FIGURE_NETWORK_CUTOFF, 1), guide = "none") +
    ggplot2::guides(size = ggplot2::guide_legend(nrow = 1,
      override.aes = list(shape = 21, fill = "white", colour = "#171717"))) +
    ggplot2::coord_cartesian(xlim = c(0, FIGURE_WIDTH_MM), ylim = c(0, panel_height_mm),
                             expand = FALSE, clip = "off") +
    ggplot2::labs(title = title, x = NULL, y = NULL) + theme_pathway_network(title_colour)
  list(plot = plot, connected_nodes = network_nodes, plot_nodes = plot_nodes,
       plot_edges = plot_edges, module_key = module_key)
}


render_plot_device <- function(open_device, plot) {
  open_device()
  device_id <- grDevices::dev.cur()
  on.exit({
    devices <- grDevices::dev.list()
    if (!is.null(devices) && device_id %in% devices) {
      grDevices::dev.off(device_id)
    }
  }, add = TRUE)
  print(plot)
  grDevices::dev.off(device_id)
  invisible(NULL)
}

save_publication_figure <- function(plot, stem) {
  width_in <- FIGURE_WIDTH_MM / 25.4
  height_in <- FIGURE_HEIGHT_MM / 25.4

  render_plot_device(
    function() svglite::svglite(
      paste0(stem, ".svg"), width = width_in, height = height_in,
      bg = "white", pointsize = 7
    ),
    plot
  )
  render_plot_device(
    # Keep editable Helvetica text and vector plotting symbols. Base PDF also
    # retains separate text runs for reliable label-collision inspection.
    function() grDevices::pdf(
      paste0(stem, ".pdf"), width = width_in, height = height_in,
      family = "Helvetica", onefile = TRUE, bg = "white", useDingbats = FALSE
    ),
    plot
  )
  render_plot_device(
    function() ragg::agg_tiff(
      paste0(stem, ".tiff"), width = width_in, height = height_in,
      units = "in", res = FIGURE_TIFF_DPI, compression = "lzw",
      background = "white"
    ),
    plot
  )
  render_plot_device(
    function() ragg::agg_png(
      paste0(stem, ".png"), width = width_in, height = height_in,
      units = "in", res = FIGURE_PREVIEW_DPI, background = "white"
    ),
    plot
  )
}

split_gmt <- function(path, wanted_terms = NULL) {
  records <- strsplit(readLines(path, warn = FALSE, encoding = "UTF-8"), "\t", fixed = TRUE)
  records <- records[lengths(records) >= 3]
  ids <- vapply(records, function(record) record[[2]], character(1))
  if (!is.null(wanted_terms)) records <- records[ids %in% wanted_terms]
  stats::setNames(lapply(records, function(record) unique(record[-c(1, 2)])),
                  vapply(records, function(record) record[[2]], character(1)))
}

empty_edges <- function() {
  data.frame(
    from_uid = character(), to_uid = character(), similarity = numeric(),
    stringsAsFactors = FALSE
  )
}

clean_gene_ids <- function(x) {
  values <- trimws(as.character(x))
  unique(values[!is.na(values) & nzchar(values)])
}

jaccard_matrix <- function(ids, gene_sets) {
  ids <- as.character(ids)
  result <- diag(1, length(ids), length(ids))
  dimnames(result) <- list(ids, ids)
  if (length(ids) < 2) return(result)
  for (i in seq_len(length(ids) - 1L)) {
    a <- clean_gene_ids(gene_sets[[ids[i]]])
    for (j in (i + 1L):length(ids)) {
      b <- clean_gene_ids(gene_sets[[ids[j]]])
      union_size <- length(union(a, b))
      similarity <- if (union_size == 0L) 0 else length(intersect(a, b)) / union_size
      result[i, j] <- similarity
      result[j, i] <- similarity
    }
  }
  result
}

matrix_to_edges <- function(similarity, cutoff) {
  if (nrow(similarity) < 2) return(empty_edges())
  indices <- which(upper.tri(similarity) & !is.na(similarity) & similarity >= cutoff,
                   arr.ind = TRUE)
  if (nrow(indices) == 0) return(empty_edges())
  data.frame(
    from_uid = rownames(similarity)[indices[, 1]],
    to_uid = colnames(similarity)[indices[, 2]],
    similarity = as.numeric(similarity[indices]),
    stringsAsFactors = FALSE
  )
}

stable_community_ids <- function(raw_membership) {
  groups <- split(names(raw_membership), unname(raw_membership))
  group_order <- order(vapply(groups, function(x) sort(x)[1], character(1)))
  mapping <- stats::setNames(seq_along(group_order), names(groups)[group_order])
  as.integer(mapping[as.character(raw_membership)])
}

detect_modules <- function(node_uids, edges, prefix) {
  node_uids <- as.character(node_uids)
  if (anyNA(node_uids) || any(!nzchar(node_uids))) {
    stop("Missing/empty vertex name in ", prefix)
  }
  if (anyDuplicated(node_uids)) {
    duplicates <- unique(node_uids[duplicated(node_uids)])
    stop("Duplicate vertex names in ", prefix, ": ", paste(duplicates, collapse = ", "))
  }
  vertices <- data.frame(name = node_uids, stringsAsFactors = FALSE)
  graph <- igraph::graph_from_data_frame(edges, directed = FALSE, vertices = vertices)

  if (nrow(edges) == 0L) {
    membership <- seq_along(node_uids)
    names(membership) <- node_uids
  } else {
    # The paper specifies edge-betweenness topology, not weighted shortest paths.
    # weights = NA prevents igraph from treating similarity as a distance.
    clustering <- igraph::cluster_edge_betweenness(
      graph, directed = FALSE, weights = NA, merges = TRUE, modularity = TRUE
    )
    raw_membership <- igraph::membership(clustering)
    membership <- stable_community_ids(raw_membership)
    names(membership) <- names(raw_membership)
  }

  module_number <- membership[node_uids]
  module_id <- paste0(prefix, "_M", sprintf("%03d", module_number))
  names(module_id) <- node_uids
  list(graph = graph, module_id = module_id)
}

choose_representatives <- function(nodes, module_column) {
  nodes |>
    dplyr::arrange(.data[[module_column]], .data$p_adjust, .data$p_value,
                   .data$database, .data$term_id) |>
    dplyr::group_by(.data[[module_column]]) |>
    dplyr::mutate(
      module_size = dplyr::n(),
      is_representative = dplyr::row_number() == 1L
    ) |>
    dplyr::ungroup()
}

write_graphml <- function(nodes, edges, path) {
  vertices <- nodes |>
    dplyr::mutate(
      name = .data$term_uid,
      label = .data$description
    ) |>
    dplyr::select(
      "name", "label", "database", "term_id", "p_adjust", "minus_log10_fdr",
      dplyr::everything()
    )
  edge_df <- edges |>
    dplyr::transmute(from = .data$from_uid, to = .data$to_uid, similarity = .data$similarity)
  graph <- igraph::graph_from_data_frame(edge_df, directed = FALSE, vertices = vertices)
  igraph::write_graph(graph, path, format = "graphml")
}


# =============================================================================
# 3. Read enrichment results and reconstruct complete pathway gene sets
# =============================================================================

prepare_enrichment <- function(df, threshold) {
  assert_columns(
    df, c("ID", "Description", "database", "pvalue", "p.adjust",
          "crest_id", "crest_label", "peak_age"), "Complete enrichment table"
  )
  for (column in c("ID", "database", "crest_id", "crest_label")) {
    df[[column]] <- as.character(df[[column]])
    if (anyNA(df[[column]]) || any(!nzchar(trimws(df[[column]])))) {
      stop("Missing/empty ", column, " in complete enrichment table")
    }
  }
  unknown_databases <- setdiff(unique(df$database), names(DATABASE_SHAPES))
  if (length(unknown_databases)) {
    stop("Unsupported enrichment database: ", paste(unknown_databases, collapse = ", "))
  }
  for (column in c("pvalue", "p.adjust", "peak_age")) {
    original <- df[[column]]
    df[[column]] <- suppressWarnings(as.numeric(original))
    if (any(!is.na(original) & is.na(df[[column]]))) stop("Non-numeric ", column)
  }
  for (column in c("pvalue", "p.adjust")) {
    values <- df[[column]]
    if (any(!is.na(values) & (!is.finite(values) | values < 0 | values > 1))) {
      stop(column, " must contain probabilities in [0, 1] or NA")
    }
  }
  if (any(!is.finite(df$peak_age))) stop("Non-finite peak_age in enrichment table")
  if (anyDuplicated(df[c("crest_id", "database", "ID")])) {
    stop("Duplicate crest/database/term key in complete enrichment table")
  }
  crests <- df |>
    dplyr::distinct(.data$crest_id, .data$crest_label, .data$peak_age)
  if (anyDuplicated(crests$crest_id)) stop("Conflicting metadata for the same crest")
  # Keep imported P values unchanged: upstream BH families are crest x database.
  significant <- df |>
    dplyr::filter(is.finite(.data$p.adjust), .data$p.adjust < threshold)
  nodes <- significant |>
    dplyr::transmute(
      crest_id = .data$crest_id, crest_label = .data$crest_label,
      peak_age = .data$peak_age, database = .data$database,
      term_id = as.character(.data$ID),
      term_uid = paste(.data$database, .data$ID, sep = "::"),
      description = as.character(.data$Description),
      p_value = .data$pvalue, p_adjust = .data$p.adjust,
      minus_log10_fdr = -log10(pmax(.data$p.adjust, .Machine$double.xmin))
    ) |>
    dplyr::arrange(.data$peak_age, .data$crest_id, .data$database,
                   .data$p_adjust, .data$p_value, .data$term_id)
  list(full = df, significant = significant, nodes = nodes, crests = crests)
}

ENRICHMENT_FILE <- assert_file(ENRICHMENT_FILE)
enrichment_input <- prepare_enrichment(
  data.table::fread(ENRICHMENT_FILE, data.table = FALSE), FDR_THRESHOLD
)
all_nodes <- enrichment_input$nodes
crest_metadata <- enrichment_input$crests
input_crest_file <- file.path(dirname(ENRICHMENT_FILE), "input_crests.csv")
if (file.exists(input_crest_file)) {
  saved_crests <- data.table::fread(input_crest_file, data.table = FALSE)
  assert_columns(saved_crests, c("crest_id", "crest_label", "peak_age"), "Saved crests")
  saved_crests <- saved_crests |>
    dplyr::transmute(crest_id = as.character(.data$crest_id),
                     crest_label = as.character(.data$crest_label),
                     peak_age = as.numeric(.data$peak_age))
  if (anyDuplicated(saved_crests$crest_id) || anyNA(saved_crests) ||
      any(!nzchar(saved_crests$crest_id)) || any(!is.finite(saved_crests$peak_age))) {
    stop("Invalid saved crest metadata")
  }
  if (nrow(dplyr::anti_join(crest_metadata, saved_crests,
                           by = c("crest_id", "crest_label", "peak_age")))) {
    stop("Complete enrichment table and input_crests.csv describe different crests")
  }
  crest_metadata <- saved_crests
}
crest_metadata <- dplyr::arrange(crest_metadata, .data$peak_age, .data$crest_id)
if (!nrow(crest_metadata)) stop("No crest metadata; retain upstream input_crests.csv")
input_counts <- enrichment_input$full |>
  dplyr::group_by(.data$crest_id, .data$database) |>
