    n_tested = dplyr::n(),
    n_missing_fdr = sum(!is.finite(.data$p.adjust)),
    n_significant = sum(is.finite(.data$p.adjust) & .data$p.adjust < FDR_THRESHOLD),
    .groups = "drop"
  )
input_counts <- merge(crest_metadata, data.frame(database = names(DATABASE_SHAPES)), by = NULL) |>
  dplyr::left_join(input_counts, by = c("crest_id", "database")) |>
  dplyr::mutate(dplyr::across(c("n_tested", "n_missing_fdr", "n_significant"),
                             function(x) dplyr::coalesce(x, 0L))) |>
  dplyr::arrange(.data$peak_age, .data$crest_id, .data$database)
data.table::fwrite(input_counts, file.path(OUTPUT_DIR, "input_term_counts_by_crest_database.csv"))
data.table::fwrite(enrichment_input$significant,
                   file.path(OUTPUT_DIR, "network_input_significant_pathways.csv"))
data.table::fwrite(crest_metadata, file.path(OUTPUT_DIR, "input_crests.csv"))
upstream_manifest <- file.path(dirname(ENRICHMENT_FILE), "analysis_manifest.txt")
if (file.exists(upstream_manifest)) {
  invisible(file.copy(upstream_manifest, file.path(OUTPUT_DIR, "enrichment_analysis_manifest.txt"),
                       overwrite = TRUE))
}
message("Read ", nrow(enrichment_input$full), " tested terms; ", nrow(all_nodes),
        " pass saved BH-adjusted P < ", FDR_THRESHOLD,
        ". No enrichment rerun; no top-N input filter.")

# Missing local annotations never remove significant nodes. Empty memberships
# have zero Jaccard overlap and are recorded explicitly in the output.
select_local_annotations <- function(ids, keytype, columns) {
  ids <- intersect(clean_gene_ids(ids), AnnotationDbi::keys(
    org.Hs.eg.db::org.Hs.eg.db, keytype = keytype
  ))
  if (!length(ids)) {
    return(as.data.frame(stats::setNames(
      rep(list(character()), length(c(keytype, columns))), c(keytype, columns)
    )))
  }
  suppressMessages(AnnotationDbi::select(
    org.Hs.eg.db::org.Hs.eg.db, keys = ids, columns = columns, keytype = keytype
  ))
}

# GO BP memberships include descendant annotations (GOALL), matching semantic
# parent/child relationships rather than only direct annotations.
go_ids <- unique(all_nodes$term_id[all_nodes$database == "GO Biological Process"])
go_map <- select_local_annotations(go_ids, "GOALL", c("ENTREZID", "ONTOLOGYALL")) |>
  dplyr::filter(.data$ONTOLOGYALL == "BP", !is.na(.data$ENTREZID)) |>
  dplyr::distinct(.data$GOALL, .data$ENTREZID)
go_sets <- split(as.character(go_map$ENTREZID), go_map$GOALL)

kegg_ids <- unique(all_nodes$term_id[all_nodes$database == "KEGG"])
kegg_paths <- sub("^hsa", "", kegg_ids)
kegg_map <- select_local_annotations(kegg_paths, "PATH", "ENTREZID") |>
  dplyr::filter(!is.na(.data$ENTREZID)) |>
  dplyr::mutate(term_id = paste0("hsa", .data$PATH)) |>
  dplyr::distinct(.data$term_id, .data$ENTREZID)
kegg_sets <- split(as.character(kegg_map$ENTREZID), kegg_map$term_id)

reactome_ids <- unique(all_nodes$term_id[all_nodes$database == "Reactome"])
reactome_symbol_sets <- if (length(reactome_ids)) {
  split_gmt(assert_file(REACTOME_GMT_FILE), reactome_ids)
} else list()
reactome_symbols <- unique(unlist(reactome_symbol_sets, use.names = FALSE))
reactome_map <- select_local_annotations(reactome_symbols, "SYMBOL", "ENTREZID") |>
  dplyr::filter(!is.na(.data$ENTREZID)) |>
  dplyr::distinct(.data$SYMBOL, .data$ENTREZID)
symbol_to_entrez <- split(as.character(reactome_map$ENTREZID), reactome_map$SYMBOL)
reactome_sets <- lapply(reactome_symbol_sets, function(symbols) {
  unique(unlist(symbol_to_entrez[symbols], use.names = FALSE))
})

term_sets <- c(go_sets, kegg_sets, reactome_sets)
term_gene_set <- function(database, term_id) {
  values <- term_sets[[term_id]]
  if (is.null(values)) character() else clean_gene_ids(values)
}
all_nodes$gene_set_size <- lengths(Map(
  term_gene_set, all_nodes$database, all_nodes$term_id
))
all_nodes$membership_status <- ifelse(all_nodes$gene_set_size > 0L,
                                    "mapped", "no_local_gene_membership")
data.table::fwrite(all_nodes, file.path(OUTPUT_DIR, "pathway_annotation_coverage.csv"))
if (any(all_nodes$gene_set_size == 0L)) {
  warning(sum(all_nodes$gene_set_size == 0L),
          " significant terms lack local gene memberships; their Jaccard similarities are zero.")
}

go_semantic_data <- if (length(go_ids)) GOSemSim::godata(
  annoDb = "org.Hs.eg.db", ont = "BP", computeIC = FALSE
) else NULL


# =============================================================================
# 4. Stage 1: within-database similarity networks and representatives
# =============================================================================

empty_network_edges <- function() {
  data.frame(crest_id = character(), crest_label = character(), stage = character(),
             database = character(), metric = character(), cutoff = numeric(),
             from_uid = character(), to_uid = character(), similarity = numeric())
}
stage1_template <- all_nodes[0, ] |>
  dplyr::mutate(stage1_module_id = character(), stage1_module_size = integer(),
                is_stage1_representative = logical())
stage1_results <- list(list(nodes = stage1_template, edges = empty_network_edges()))
stage1_index <- 0L

for (crest in sort(unique(all_nodes$crest_id))) {
  for (database in c("GO Biological Process", "KEGG", "Reactome")) {
    nodes <- all_nodes |>
      dplyr::filter(.data$crest_id == crest, .data$database == .env$database) |>
      dplyr::arrange(.data$p_adjust, .data$term_id)
    if (nrow(nodes) == 0L) next

    ids <- nodes$term_id
    if (database == "GO Biological Process") {
      similarity <- GOSemSim::mgoSim(
        ids, ids, semData = go_semantic_data, measure = "Wang", combine = NULL
      )
      similarity[is.na(similarity)] <- 0
      diag(similarity) <- 1
      rownames(similarity) <- nodes$term_uid
      colnames(similarity) <- nodes$term_uid
      cutoff <- GO_NETWORK_CUTOFF
      metric <- "Wang"
    } else {
      uid_sets <- stats::setNames(lapply(ids, function(id) term_sets[[id]]), nodes$term_uid)
      similarity <- jaccard_matrix(nodes$term_uid, uid_sets)
      cutoff <- if (database == "KEGG") KEGG_NETWORK_CUTOFF else REACTOME_NETWORK_CUTOFF
      metric <- "Jaccard"
    }

    edges <- matrix_to_edges(similarity, cutoff)
    db_token <- if (database == "GO Biological Process") "GO_BP" else database
    prefix <- paste0("C", safe_token(crest), "_", safe_token(db_token))
    message("Stage 1: ", prefix, " (", nrow(nodes), " nodes, ", nrow(edges), " edges)")
    modules <- detect_modules(nodes$term_uid, edges, prefix)
    nodes$stage1_module_id <- unname(modules$module_id[nodes$term_uid])
    nodes <- choose_representatives(nodes, "stage1_module_id") |>
      dplyr::rename(
        stage1_module_size = "module_size",
        is_stage1_representative = "is_representative"
      )

    if (nrow(edges) > 0L) {
      edges <- edges |>
        dplyr::mutate(
          crest_id = crest,
          crest_label = nodes$crest_label[1],
          database = database,
          metric = metric,
          cutoff = cutoff,
          stage = "within_database"
        ) |>
        dplyr::select(
          "crest_id", "crest_label", "stage", "database", "metric", "cutoff",
          "from_uid", "to_uid", "similarity"
        )
    } else {
      edges <- data.frame(
        crest_id = character(), crest_label = character(), stage = character(),
        database = character(), metric = character(), cutoff = numeric(),
        from_uid = character(), to_uid = character(), similarity = numeric(),
        stringsAsFactors = FALSE
      )
    }

    stage1_index <- stage1_index + 1L
    stage1_results[[stage1_index]] <- list(nodes = nodes, edges = edges)
  }
}

stage1_nodes <- dplyr::bind_rows(lapply(stage1_results, function(result) result$nodes)) |>
  dplyr::arrange(.data$crest_id, .data$database, .data$stage1_module_id,
                 .data$p_adjust, .data$term_id)
stage1_edges <- dplyr::bind_rows(lapply(stage1_results, function(result) result$edges)) |>
  dplyr::arrange(.data$crest_id, .data$database, dplyr::desc(.data$similarity),
                 .data$from_uid, .data$to_uid)
stage1_representatives <- stage1_nodes |>
  dplyr::filter(.data$is_stage1_representative)

data.table::fwrite(stage1_nodes, file.path(OUTPUT_DIR, "stage1_nodes.csv"))
data.table::fwrite(stage1_edges, file.path(OUTPUT_DIR, "stage1_edges.csv"))
data.table::fwrite(
  stage1_representatives, file.path(OUTPUT_DIR, "stage1_module_representatives.csv")
)
# Write every crest/database combination, including empty graphs, so a stricter
# FDR on rerun cannot leave a previous nonempty graph masquerading as current.
for (crest in crest_metadata$crest_id) {
  for (database in names(DATABASE_SHAPES)) {
    db_token <- if (database == "GO Biological Process") "GO_BP" else database
    prefix <- paste0("C", safe_token(crest), "_", safe_token(db_token))
    write_graphml(
      dplyr::filter(stage1_nodes, .data$crest_id == crest, .data$database == .env$database),
      dplyr::filter(stage1_edges, .data$crest_id == crest, .data$database == .env$database),
      file.path(OUTPUT_DIR, paste0(prefix, "_stage1_network.graphml"))
    )
  }
}


# =============================================================================
# 5. Stage 2: cross-database Jaccard network and final functional modules
# =============================================================================

final_template <- stage1_representatives[0, ] |>
  dplyr::mutate(final_module_id = character(), final_module_size = integer(),
                is_final_representative = logical())
final_results <- list(list(nodes = final_template, edges = empty_network_edges()))
final_index <- 0L

for (crest in sort(unique(stage1_representatives$crest_id))) {
  nodes <- stage1_representatives |>
    dplyr::filter(.data$crest_id == crest) |>
    dplyr::arrange(.data$p_adjust, .data$database, .data$term_id)
  uid_sets <- stats::setNames(
    lapply(seq_len(nrow(nodes)), function(i) term_sets[[nodes$term_id[i]]]),
    nodes$term_uid
  )
  similarity <- jaccard_matrix(nodes$term_uid, uid_sets)
  edges <- matrix_to_edges(similarity, MERGED_NETWORK_CUTOFF)
  prefix <- paste0("C", safe_token(crest), "_FINAL")
  message("Stage 2: ", prefix, " (", nrow(nodes), " nodes, ", nrow(edges), " edges)")
  modules <- detect_modules(nodes$term_uid, edges, prefix)
  nodes$final_module_id <- unname(modules$module_id[nodes$term_uid])
  nodes <- choose_representatives(nodes, "final_module_id") |>
    dplyr::rename(
      final_module_size = "module_size",
      is_final_representative = "is_representative"
    )

  if (nrow(edges) > 0L) {
    edges <- edges |>
      dplyr::mutate(
        crest_id = crest,
        crest_label = nodes$crest_label[1],
        stage = "cross_database",
        database = "Merged GO BP + KEGG + Reactome",
        metric = "Jaccard",
        cutoff = MERGED_NETWORK_CUTOFF
      ) |>
      dplyr::select(
        "crest_id", "crest_label", "stage", "database", "metric", "cutoff",
        "from_uid", "to_uid", "similarity"
      )
  } else {
    edges <- data.frame(
      crest_id = character(), crest_label = character(), stage = character(),
      database = character(), metric = character(), cutoff = numeric(),
      from_uid = character(), to_uid = character(), similarity = numeric(),
      stringsAsFactors = FALSE
    )
  }

  final_index <- final_index + 1L
  final_results[[final_index]] <- list(nodes = nodes, edges = edges)
}

final_nodes <- dplyr::bind_rows(lapply(final_results, function(result) result$nodes)) |>
  dplyr::arrange(.data$crest_id, .data$final_module_id, .data$p_adjust, .data$term_id)
final_edges <- dplyr::bind_rows(lapply(final_results, function(result) result$edges)) |>
  dplyr::arrange(.data$crest_id, dplyr::desc(.data$similarity),
                 .data$from_uid, .data$to_uid)

final_modules <- final_nodes |>
  dplyr::group_by(
    .data$crest_id, .data$crest_label, .data$peak_age, .data$final_module_id
  ) |>
  dplyr::summarise(
    module_size = dplyr::n(),
    n_databases = dplyr::n_distinct(.data$database),
    databases = paste(sort(unique(.data$database)), collapse = ";"),
    representative_uid = .data$term_uid[.data$is_final_representative][1],
    representative_id = .data$term_id[.data$is_final_representative][1],
    representative_description = .data$description[.data$is_final_representative][1],
    representative_database = .data$database[.data$is_final_representative][1],
    representative_p_adjust = .data$p_adjust[.data$is_final_representative][1],
    representative_p_value = .data$p_value[.data$is_final_representative][1],
    member_uids = paste(.data$term_uid, collapse = " | "),
    member_descriptions = paste(.data$description, collapse = " | "),
    .groups = "drop"
  ) |>
  dplyr::arrange(.data$crest_id, .data$representative_p_adjust,
                 .data$representative_p_value, .data$representative_database,
                 .data$representative_id)

# Propagate both reduction stages back to every significant input term. Final
# network nodes are stage-1 representatives, so the final network alone cannot
# describe the complete membership of each functional module.
pathway_assignments <- stage1_nodes |>
  dplyr::left_join(
    final_nodes |>
      dplyr::transmute(crest_id = .data$crest_id, stage1_module_id = .data$stage1_module_id,
                       stage1_representative_uid = .data$term_uid,
                       final_module_id = .data$final_module_id),
    by = c("crest_id", "stage1_module_id")
  ) |>
  dplyr::left_join(
    final_modules |>
      dplyr::select("crest_id", "final_module_id", "representative_uid",
                     "representative_id", "representative_description",
                     "representative_database", "representative_p_adjust"),
    by = c("crest_id", "final_module_id")
  ) |>
  dplyr::mutate(is_final_representative = .data$term_uid == .data$representative_uid) |>
  dplyr::arrange(.data$peak_age, .data$crest_id, .data$final_module_id,
                 .data$p_adjust, .data$p_value, .data$database, .data$term_id)
if (nrow(pathway_assignments) != nrow(all_nodes) || anyNA(pathway_assignments$final_module_id)) {
  stop("Module assignment must retain every significant input pathway exactly once")
}
original_module_members <- pathway_assignments |>
  dplyr::group_by(.data$crest_id, .data$final_module_id) |>
  dplyr::summarise(
    n_original_pathways = dplyr::n(),
    n_original_databases = dplyr::n_distinct(.data$database),
    original_databases = paste(sort(unique(.data$database)), collapse = ";"),
    original_member_uids = paste(.data$term_uid, collapse = " | "),
    .groups = "drop"
  )
final_modules <- dplyr::left_join(final_modules, original_module_members,
                                 by = c("crest_id", "final_module_id"))
data.table::fwrite(pathway_assignments, file.path(OUTPUT_DIR, "pathway_module_assignments.csv"))
data.table::fwrite(
  final_nodes |>
    dplyr::filter(.data$is_final_representative) |>
    dplyr::left_join(original_module_members, by = c("crest_id", "final_module_id")),
  file.path(OUTPUT_DIR, "nonredundant_pathways.csv")
)

data.table::fwrite(final_nodes, file.path(OUTPUT_DIR, "final_network_nodes.csv"))
data.table::fwrite(final_edges, file.path(OUTPUT_DIR, "final_network_edges.csv"))
data.table::fwrite(final_modules, file.path(OUTPUT_DIR, "final_functional_modules.csv"))


# =============================================================================
# 6. Full GraphML exports and top-15 final-module figures (Jaccard >= 0.1)
# =============================================================================

empty_figure_result <- function(nodes) {
  nodes <- nodes[0, ] |>
    dplyr::mutate(figure_module_rank = integer(), is_connected = logical())
  connected <- nodes |>
    dplyr::mutate(display_module_rank = integer(), module_tag = character(),
                  network_label = character(), displayed_representative_uid = character(),
                  n_pathways = integer(), n_databases = integer(),
                  display_community_id = character(), display_community = character(),
                  n_community_pathways = integer(),
                  is_display_representative = logical(), figure_minus_log10_fdr = numeric())
  edges <- empty_network_edges()
  list(
    nodes = nodes, connected_nodes = connected, edges = edges,
    plot_nodes = dplyr::mutate(connected, x = numeric(), y = numeric()),
    plot_edges = dplyr::mutate(edges, within_module = logical(),
                              x_from = numeric(), y_from = numeric(),
                              x_to = numeric(), y_to = numeric()),
    module_key = data.frame(
      crest_id = character(), crest_label = character(), peak_age = numeric(),
      final_module_id = character(), figure_module_rank = integer(),
      displayed_representative_uid = character(), representative_description = character(),
      representative_database = character(), representative_p_adjust = numeric(),
      n_pathways = integer(), n_databases = integer(), databases = character(),
      display_module_rank = integer(), module_tag = character(), module_detail = character(),
      network_label = character()
    )
  )
}
save_network_placeholder <- function(label, detail, stem, title_colour) {
  plot <- ggplot2::ggplot() +
    ggplot2::annotate("text", x = 0, y = 0, label = detail,
                      size = 6 / PT_PER_MM, family = "Helvetica", colour = "#4F5660") +
    ggplot2::xlim(-1, 1) + ggplot2::ylim(-1, 1) +
    ggplot2::labs(title = label) + theme_pathway_network(title_colour)
  save_publication_figure(plot, stem)
}
figure_results <- list(empty_figure_result(final_nodes))
figure_index <- 0L
crest_levels <- crest_metadata$crest_id
fdr_size_min <- -log10(FDR_THRESHOLD)
if (FDR_SIZE_CAP <= fdr_size_min) {
  stop("PATHWAY_NETWORK_FDR_SIZE_CAP must exceed -log10(PATHWAY_NETWORK_FDR)")
}
fdr_size_breaks <- sort(unique(c(2, 5, FDR_SIZE_CAP)))
fdr_size_breaks <- fdr_size_breaks[
  fdr_size_breaks >= fdr_size_min & fdr_size_breaks <= FDR_SIZE_CAP
]
fdr_size_labels <- format(fdr_size_breaks, trim = TRUE, scientific = FALSE)
fdr_size_labels[length(fdr_size_labels)] <- paste0(">=", fdr_size_labels[length(fdr_size_labels)])
panel_height_mm <- FIGURE_HEIGHT_MM - 9
if (panel_height_mm < 20) stop("The network figure height must be at least 29 mm")

for (crest in crest_levels) {
  crest_info <- crest_metadata[crest_metadata$crest_id == crest, ]
  crest_display_label <- paste0("Crest", match(crest, crest_levels))
  crest_title_colour <- rep(CREST_TITLE_COLOURS, length.out = length(crest_levels))[
    match(crest, crest_levels)
  ]
  complete_nodes <- final_nodes |>
    dplyr::filter(.data$crest_id == crest)
  complete_edges <- final_edges |>
    dplyr::filter(.data$crest_id == crest)
  crest_token <- paste0(
    "crest_", safe_token(crest), "_age_",
    safe_token(format_age(crest_info$peak_age[1]))
  )

  # Preserve the complete second-stage functional-module network for Cytoscape.
  graphml_path <- file.path(OUTPUT_DIR, paste0(crest_token, "_final_network.graphml"))
  write_graphml(complete_nodes, complete_edges, graphml_path)
  if (!nrow(complete_nodes)) {
    save_network_placeholder(
      crest_display_label, "No significant pathways",
      file.path(FIGURE_DIR, paste0(crest_token, "_pathway_similarity_network")),
      crest_title_colour
    )
    write_graphml(complete_nodes, complete_edges,
                  file.path(OUTPUT_DIR, paste0(crest_token, "_top15_connected_figure_network.graphml")))
    next
  }

  # Jia-style display: one final representative per selected module. Display
  # communities are detected anew at the figure cutoff and do not replace the
  # full analysis module assignments.
  selected_modules <- complete_nodes |>
    dplyr::filter(.data$is_final_representative) |>
    dplyr::arrange(.data$p_adjust, .data$p_value, .data$database, .data$term_id) |>
    dplyr::slice_head(n = TOP_N_FINAL_MODULES) |>
    dplyr::transmute(
      final_module_id = .data$final_module_id,
      figure_module_rank = dplyr::row_number()
    )
  nodes <- complete_nodes |>
    dplyr::filter(.data$is_final_representative) |>
    dplyr::inner_join(selected_modules, by = "final_module_id") |>
    dplyr::arrange(.data$figure_module_rank, .data$p_adjust, .data$term_id)
  uid_sets <- stats::setNames(
    lapply(seq_len(nrow(nodes)), function(i) term_sets[[nodes$term_id[i]]]),
    nodes$term_uid
  )
  figure_similarity <- jaccard_matrix(nodes$term_uid, uid_sets)
  edges <- matrix_to_edges(figure_similarity, FIGURE_NETWORK_CUTOFF)
  if (nrow(edges) > 0L) {
    edges <- edges |>
      dplyr::mutate(
        crest_id = crest,
        crest_label = nodes$crest_label[1],
        stage = "figure_top15_connected",
        database = "Merged GO BP + KEGG + Reactome",
        metric = "Jaccard",
        cutoff = FIGURE_NETWORK_CUTOFF
      ) |>
      dplyr::select(
        "crest_id", "crest_label", "stage", "database", "metric", "cutoff",
        "from_uid", "to_uid", "similarity"
      )
  } else {
    edges <- data.frame(
      crest_id = character(), crest_label = character(), stage = character(),
      database = character(), metric = character(), cutoff = numeric(),
      from_uid = character(), to_uid = character(), similarity = numeric(),
      stringsAsFactors = FALSE
    )
  }

  connected_uids <- unique(c(edges$from_uid, edges$to_uid))
  nodes <- nodes |>
    dplyr::mutate(is_connected = .data$term_uid %in% connected_uids)
  network_nodes <- nodes |>
    dplyr::filter(.data$is_connected)
  if (nrow(network_nodes) == 0L) {
    message("Crest ", crest, ": no connected display nodes; all modules remain in full results.")
    save_network_placeholder(
      crest_display_label, "No connected pathways to display",
      file.path(FIGURE_DIR, paste0(crest_token, "_pathway_similarity_network")),
      crest_title_colour
    )
    write_graphml(network_nodes, edges,
                  file.path(OUTPUT_DIR, paste0(crest_token, "_top15_connected_figure_network.graphml")))
    figure_index <- figure_index + 1L
    figure_results[[figure_index]] <- empty_figure_result(final_nodes)
    figure_results[[figure_index]]$nodes <- nodes
    next
  }

  reference_figure <- build_reference_network_figure(
    network_nodes, edges, crest_display_label, crest_title_colour,
    seed = 4200L + match(crest, crest_levels)
  )
  network_nodes <- reference_figure$connected_nodes
  plot_nodes <- reference_figure$plot_nodes
  plot_edges <- reference_figure$plot_edges
  module_summary <- reference_figure$module_key
  write_graphml(
    plot_nodes, edges,
    file.path(OUTPUT_DIR, paste0(crest_token, "_top15_connected_figure_network.graphml"))
  )
  figure_stem <- file.path(FIGURE_DIR, paste0(crest_token, "_pathway_similarity_network"))
  save_publication_figure(reference_figure$plot, figure_stem)

  figure_index <- figure_index + 1L
  figure_results[[figure_index]] <- list(
    nodes = nodes,
    connected_nodes = network_nodes,
    edges = edges,
    plot_nodes = plot_nodes,
    plot_edges = plot_edges,
    module_key = module_summary
  )
}

figure_nodes <- dplyr::bind_rows(lapply(figure_results, function(result) result$nodes)) |>
  dplyr::arrange(.data$crest_id, .data$figure_module_rank, .data$p_adjust, .data$term_id)
figure_connected_nodes <- dplyr::bind_rows(
  lapply(figure_results, function(result) result$connected_nodes)
) |>
  dplyr::arrange(.data$crest_id, .data$figure_module_rank, .data$p_adjust, .data$term_id)
figure_edges <- dplyr::bind_rows(lapply(figure_results, function(result) result$edges)) |>
  dplyr::arrange(.data$crest_id, dplyr::desc(.data$similarity),
                 .data$from_uid, .data$to_uid)
figure_plot_nodes <- dplyr::bind_rows(lapply(figure_results, function(result) result$plot_nodes)) |>
  dplyr::arrange(
    .data$crest_id, .data$display_module_rank, .data$p_adjust, .data$term_id
  )
figure_plot_edges <- dplyr::bind_rows(lapply(figure_results, function(result) result$plot_edges)) |>
  dplyr::arrange(
    .data$crest_id, dplyr::desc(.data$similarity), .data$from_uid, .data$to_uid
  )
figure_module_key <- dplyr::bind_rows(lapply(figure_results, function(result) result$module_key)) |>
  dplyr::arrange(.data$crest_id, .data$display_module_rank)
data.table::fwrite(figure_nodes, file.path(OUTPUT_DIR, "figure_top15_nodes.csv"))
data.table::fwrite(
  figure_connected_nodes,
  file.path(OUTPUT_DIR, "figure_top15_connected_nodes.csv")
)
data.table::fwrite(figure_edges, file.path(OUTPUT_DIR, "figure_top15_edges.csv"))
data.table::fwrite(
  figure_plot_nodes, file.path(OUTPUT_DIR, "figure_network_plot_nodes.csv")
)
data.table::fwrite(
  figure_plot_edges, file.path(OUTPUT_DIR, "figure_network_plot_edges.csv")
)
data.table::fwrite(
  figure_module_key, file.path(OUTPUT_DIR, "figure_network_module_key.csv")
)
figure_communities <- figure_connected_nodes |>
  dplyr::group_by(.data$crest_id, .data$crest_label, .data$peak_age,
                  .data$display_community_id, .data$display_community) |>
  dplyr::summarise(
    n_representative_pathways = dplyr::n(),
    final_module_ids = paste(sort(.data$final_module_id), collapse = ";"),
    pathway_names = paste(sentence_case(.data$description), collapse = "; "),
    .groups = "drop"
  )
data.table::fwrite(figure_communities, file.path(OUTPUT_DIR, "figure_display_communities.csv"))


# =============================================================================
# 7. Audit trail
# =============================================================================

summary_table <- final_nodes |>
  dplyr::group_by(.data$crest_id, .data$crest_label, .data$peak_age) |>
  dplyr::summarise(
    significant_terms = sum(stage1_nodes$crest_id == dplyr::first(.data$crest_id)),
    stage1_representatives = dplyr::n(),
    final_edges = sum(final_edges$crest_id == dplyr::first(.data$crest_id)),
    final_modules = dplyr::n_distinct(.data$final_module_id),
    multi_term_modules = dplyr::n_distinct(.data$final_module_id[.data$final_module_size > 1]),
    top15_figure_edges = sum(figure_edges$crest_id == dplyr::first(.data$crest_id)),
    top15_connected_nodes = sum(
      figure_connected_nodes$crest_id == dplyr::first(.data$crest_id)
    ),
    top15_connected_modules = dplyr::n_distinct(
      figure_connected_nodes$final_module_id[
        figure_connected_nodes$crest_id == dplyr::first(.data$crest_id)
      ]
    ),
    top15_display_communities = dplyr::n_distinct(
      figure_connected_nodes$display_community_id[
        figure_connected_nodes$crest_id == dplyr::first(.data$crest_id)
      ]
    ),
    .groups = "drop"
  )
summary_table <- crest_metadata |>
  dplyr::left_join(summary_table, by = c("crest_id", "crest_label", "peak_age")) |>
  dplyr::mutate(
    dplyr::across(-c("crest_id", "crest_label", "peak_age"),
                   function(x) dplyr::coalesce(x, 0L)),
    redundant_terms = .data$significant_terms - .data$final_modules,
    figure_status = dplyr::case_when(
      .data$significant_terms == 0L ~ "no_significant_pathways",
      .data$top15_connected_nodes == 0L ~ "no_connected_display_nodes",
      TRUE ~ "rendered"
    )
  )
data.table::fwrite(summary_table, file.path(OUTPUT_DIR, "network_summary_by_crest.csv"))

# Keep the statistical and encoding details available without filling the
# 100-mm network panels with counts, database keys or similarity legends.
markdown_table_row <- function(...) paste0("| ", paste(c(...), collapse = " | "), " |")
figure_summary <- c(
  "# Pathway similarity networks: statistics and figure notes", "",
  sprintf("Figure size: %g x %g mm. Titles follow increasing peak age: Crest1 (blue), Crest2 (orange).",
          FIGURE_WIDTH_MM, FIGURE_HEIGHT_MM),
  "",
  markdown_table_row("Figure", "Peak age", "Significant pathways", "Stage-1 representatives",
                     "Final modules", "Displayed representative pathways", "Display communities", "Displayed edges"),
  "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |"
)
for (i in seq_len(nrow(summary_table))) {
  row <- summary_table[i, ]
  figure_summary <- c(figure_summary, sprintf(
    "| Crest%d | %s | %d | %d | %d | %d | %d | %d |",
    match(row$crest_id, crest_levels), format_age(row$peak_age),
    row$significant_terms, row$stage1_representatives, row$final_modules,
    row$top15_connected_nodes, row$top15_display_communities, row$top15_figure_edges
  ))
}
figure_summary <- c(
  figure_summary, "", "## Significance and similarity", "",
  sprintf("- Significant pathways: saved BH-adjusted P < %g; adjustment is inherited from each crest/database enrichment family. No P values are recalculated.", FDR_THRESHOLD),
  sprintf("- Stage 1: GO BP Wang similarity >= %g; KEGG Jaccard >= %g; Reactome Jaccard >= %g.",
          GO_NETWORK_CUTOFF, KEGG_NETWORK_CUTOFF, REACTOME_NETWORK_CUTOFF),
  sprintf("- Stage 2: cross-database Jaccard >= %g; communities use unweighted edge-betweenness topology.", MERGED_NETWORK_CUTOFF),
  sprintf("- Display: select one representative from each of the top %d final modules, then retain representatives connected by Jaccard >= %g. All pathways and modules remain in the complete analysis exports.",
          TOP_N_FINAL_MODULES, FIGURE_NETWORK_CUTOFF),
  "- Display communities: edge-betweenness communities detected anew on the representative-only display network. The coloured envelopes summarize this display graph; they are not the complete final functional modules from stage 2.",
  "- Jaccard = shared genes / union of genes, using complete local pathway memberships, not only peak-associated genes.",
  "", "## Reference implementation", "",
  "Visual adaptation: [Jia et al. repository, pathway-network visualization](https://github.com/XueqingJia/Proteomics_frailty/blob/main/2_Pathway%20enrichment%20analysis%20and%20functional%20module%20identification.R#L491-L596).",
  "The reference uses representative nodes, display-community colours, pale envelopes and nearby black labels. Its example selects 10 pathways and calculates Jaccard from enrichment geneID lists. This script retains the requested top-15 limit and its existing complete local annotation memberships. The upstream enrichment, stage-1 and stage-2 analyses are unchanged.",
  "", "## Visual encodings", "",
  "- Node colour and its pale envelope identify the display community. All pathway labels are black, close to their nodes, and shown without module IDs or counts.",
  "- Every node is a circle. Database origin is retained in the source tables rather than encoded as node shape; there is no Database legend.",
  sprintf("- Node size encodes -log10(FDR), capped at %g. Raw FDR values remain in the source tables.", FDR_SIZE_CAP),
  "- Grey edge width encodes Jaccard similarity. The Jaccard legend is omitted from the figures.",
  "- Short dotted guides are added only where a displaced label could be ambiguous. They associate text with its node and are not Jaccard network edges.",
  "- Layout coordinates have no quantitative meaning. Labels are measured at final size and placed around their own nodes while avoiding text, nodes and network edges. Rounded convex envelopes follow the actual community coordinates.",
  "- The figures have no subtitle or added outer margin. The compact FDR size key is retained.",
  "", "## Displayed representative pathways", "",
  "Each row is one representative of one final functional module. Display community IDs describe the colour groups in the figure; complete module memberships remain in final_functional_modules.csv and pathway_module_assignments.csv.", "",
  markdown_table_row("Figure", "Final module ID", "Representative pathway", "Display community", "Database"),
  "| --- | --- | --- | --- | --- |"
)
for (i in seq_len(nrow(figure_module_key))) {
  row <- figure_module_key[i, ]
  figure_summary <- c(figure_summary, sprintf(
    "| Crest%d | %s | %s | %s | %s |", match(row$crest_id, crest_levels),
    row$final_module_id, row$representative_description, row$display_community, row$databases
  ))
}
writeLines(figure_summary, file.path(OUTPUT_DIR, "network_figure_summary.md"), useBytes = TRUE)

manifest <- c(
  paste0("analysis_date=", Sys.Date()),
  paste0("enrichment_input=", ENRICHMENT_FILE),
  paste0("enrichment_input_md5=", unname(tools::md5sum(ENRICHMENT_FILE))),
  paste0("tested_terms_read=", nrow(enrichment_input$full)),
  paste0("significant_terms_used=", nrow(all_nodes)),
  "enrichment_rerun=false; P_values_and_BH_adjustment_imported_unchanged",
